function localNotes(){try{const n=JSON.parse(localStorage.getItem(NOTE_KEY)||'{}');return n&&typeof n==='object'?n:{}}catch(_){return {}}}
function cleanReason(value){return String(value||'').replaceAll('JH 公司帳號','').replace(/^\s*📢\s*/,'').replace(/\s+/g,' ').trim()}
data.forEach(row=>{row[7]=cleanReason(row[7])});
function loadNotes(){return remoteNotes}
function syncNotice(message){const e=document.querySelector('#cloudStatus');if(e)e.textContent=message}
function noteHit(r,notes){const key=rowKey(r),legacy=legacyRowKey(r),oldReason=oldReasonRowKey(r);if(typeof notes[key]==='string')return [notes[key],key];if(typeof notes[oldReason]==='string')return [notes[oldReason],oldReason];if(typeof notes[legacy]==='string')return [notes[legacy],legacy];const prefix=[r[0],r[1]].join('|')+'|';const fallback=Object.entries(notes).find(([stored,value])=>stored.startsWith(prefix)&&typeof value==='string');return fallback||['','']}
function saveNotes(){const notes=remoteNotes;data.forEach(r=>{const value=(r[12]||'').trim(),key=rowKey(r),source=r._noteSource||'';if(value){notes[key]=value;if(source&&source!==key)notes[source]=value}else{delete notes[key];if(source)delete notes[source]}});localStorage.setItem(NOTE_KEY,JSON.stringify(notes));if(cloudUser)void pushNotes()}
function applyNotes(){const notes=loadNotes();data.forEach(r=>{const [value,key]=noteHit(r,notes);r[12]=value;r._noteSource=key})}
async function loadRemoteNotes(){const {data:rows,error}=await cloudClient.from('tracker_notes').select('row_key,note').eq('tracker_id','line-stock-tracker');if(error){syncNotice('註記讀取失敗：'+error.message);return}remoteNotes={...localNotes()};for(const r of rows||[])remoteNotes[r.row_key]=r.note;applyNotes();render();syncNotice('註記已雲端同步：'+cloudUser.email)}
async function pushNotes(){if(!cloudClient||!cloudUser)return;const rows=Object.entries(remoteNotes).map(([row_key,note])=>({tracker_id:'line-stock-tracker',row_key,note}));const {error}=await cloudClient.from('tracker_notes').upsert(rows,{onConflict:'user_id,tracker_id,row_key'});if(error)syncNotice('註記儲存失敗：'+error.message);else syncNotice('註記已儲存並同步')}
async function clearNotes(){if(!confirm('確定清除所有「我的註記」嗎？此動作會同步到你的其他裝置。'))return;remoteNotes={};data.forEach(r=>{r[12]='';r._noteSource=''});localStorage.removeItem(NOTE_KEY);if(cloudClient&&cloudUser){const {error}=await cloudClient.from('tracker_notes').delete().eq('tracker_id','line-stock-tracker');syncNotice(error?'註記清除失敗：'+error.message:'註記已從雲端清除')}render()}
async function signInCloud(){const email=(document.querySelector('#cloudEmail')?.value||'').trim();if(!email){syncNotice('請輸入你的 Email');return}if(!cloudClient){syncNotice('雲端同步尚在準備；請稍後再按一次。');return}try{syncNotice('正在寄送登入連結…');const {error}=await cloudClient.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin}});syncNotice(error?'登入連結寄送失敗：'+error.message:'登入連結已寄到 Email；請在同一台裝置開啟信件中的連結，再回到本頁。')}catch(error){syncNotice('登入連線失敗：'+(error.message||'請稍後重試'))}}
async function signOutCloud(){try{if(cloudClient)await cloudClient.auth.signOut()}catch(_){}cloudUser=null;remoteNotes={...localNotes(),...remoteNotes};applyNotes();render();syncNotice('已登出；本機註記仍會保留。')}
async function initCloudNotes(){applyNotes();if(!CLOUD.supabaseUrl||!CLOUD.supabaseAnonKey||!window.supabase){syncNotice('本機註記已啟用；雲端同步尚未設定。');return}try{cloudClient=window.supabase.createClient(CLOUD.supabaseUrl,CLOUD.supabaseAnonKey);const {data:{session}}=await cloudClient.auth.getSession();cloudUser=session?.user||null;if(cloudUser)await loadRemoteNotes();else{applyNotes();syncNotice('本機註記已保存；登入僅供跨裝置同步。')}cloudClient.auth.onAuthStateChange(async(_event,session)=>{if(session?.user){cloudUser=session.user;await loadRemoteNotes()}})}catch(error){syncNotice('本機註記已保存；雲端同步暫時無法連線。')}}
function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function teacherDisplay(r){const meta=r[18]||{},base=meta.teacher_display_name||String(r[6]||'未標示').replace(/（猜）|\(猜\)/g,'').trim();return base+(meta.teacher_attribution_confidence==='INFERRED'?'（猜）':'')}
function portfolioStatus(r){const note=String(r[12]||'').trim();if(!note)return {code:'NONE',label:'—',cls:''};if(/持股|持有|部位/.test(note))return {code:'HOLDING',label:'持股',cls:'holding'};if(/觀察|追蹤|watch/i.test(note))return {code:'WATCHLIST',label:'觀察',cls:'watchlist'};return {code:'UNKNOWN',label:'註記',cls:'noted'}}
function editNote(r){const current=String(r[12]||''),next=prompt('我的註記（輸入「持股」或「觀察」可顯示對應狀態）',current);if(next===null)return;r[12]=next.trim();saveNotes();render()}
let quickFilter={type:'',value:'',label:''};
function rowTime(r){const meta=r[18]||{},full=meta.resolved_date||meta.signal_date;if(full){const t=Date.parse(full+'T00:00:00Z');if(Number.isFinite(t))return t}if(partialDate(r))return 0;const m=String(r[0]).match(/(\d{1,2})\/(\d{1,2})/);return m?Date.UTC(2026,Number(m[1])-1,Number(m[2])):0}
function partialDate(r){return Boolean(r[18]?.partial_date)}
const LATEST_SIGNAL_TIME=Math.max(...data.filter(r=>!partialDate(r)).map(rowTime));
function dateAllowed(row){const mode=document.querySelector('#dateRange').value,time=rowTime(row);if(mode==='all')return true;if(mode==='unknown')return partialDate(row);if(partialDate(row))return false;const cutoff=new Date(LATEST_SIGNAL_TIME);if(mode==='7d')cutoff.setUTCDate(cutoff.getUTCDate()-6);else if(mode==='1m')cutoff.setUTCMonth(cutoff.getUTCMonth()-1);else if(mode==='3m')cutoff.setUTCMonth(cutoff.getUTCMonth()-3);return time>=cutoff.getTime()}
function displayDate(r){const meta=r[18]||{},full=meta.resolved_date||meta.signal_date;if(full&&meta.raw_year==null&&meta.resolution_method==='SEQUENCE_RECONSTRUCTED')return `${full.replaceAll('-','/')}<br><small>重建日期</small>`;if(partialDate(r))return `${esc(r[0])}<br><small>年份未明</small>`;return esc(r[0])}
function codeOf(label){const m=String(label).match(/\b(00\d{3}[A-Z]?|\d{4})\b/);return m?.[1]||''}
function numbersOf(v){return (String(v).match(/\d+(?:\.\d+)?/g)||[]).map(Number).filter(Number.isFinite)}
function entryOf(v){const nums=numbersOf(v);return nums.length?Math.max(...nums):null}
function pctClass(v){const n=parseFloat(v);return Number.isFinite(n)?(n>=0?'profit':'loss'):''}
function statusClass(row){return row[15]==='closed'?'closed':'open'}
function toggleAnalystTable(){const wrap=document.querySelector('#analystTableWrap'),button=document.querySelector('#analystToggle');if(!wrap||!button)return;const collapsed=wrap.classList.toggle('analyst-collapsed');button.textContent=collapsed?`展開全部 ${wrap.dataset.total} 位分析師`:'收合至前 10 位分析師'}
function chooseAll(select){for(const option of select.options)option.selected=!option.value}
function updateQuickFilterStatus(){const chip=document.querySelector('#quickFilterStatus');chip.hidden=!quickFilter.type;chip.textContent=quickFilter.type?`篩選：${quickFilter.label} ×`:''}
function applyQuickFilter(type,value,label){quickFilter={type,value,label};document.querySelector('#q').value=label;populateSignalFilter();populateStatusFilter();chooseAll(document.querySelector('#signal'));chooseAll(document.querySelector('#status'));updateQuickFilterStatus();render();document.querySelector('.table-wrap').scrollIntoView({behavior:'smooth',block:'start'})}
function clearQuickFilter(){quickFilter={type:'',value:'',label:''};document.querySelector('#q').value='';updateQuickFilterStatus();render()}
function stockLink(label){const code=codeOf(label),page=location.protocol==='file:'?'https://line-stock-tracker-orqowf.pages.dev/stock.html':'stock.html';return code?`<a class="stock-link" href="${page}?code=${encodeURIComponent(code)}" target="_blank" rel="noopener" title="開啟個股研究頁">${esc(label)}</a>`:esc(label)}
function normalizePrice(v){const n=Number(v);return Number.isFinite(n)&&n>0?String(n):''}
const SIGNAL_ORDER=['買進','加碼','續抱','賣出','出場','市場訊號'];
const STATUS_ORDER=['買進','加碼','續抱','賣出一半','部分出場','全數出清','觀察市場','放空','回補'];
function chosen(select){return [...select.selectedOptions].map(option=>option.value).filter(Boolean)}
function orderSignals(values){return [...values].sort((a,b)=>{const ai=SIGNAL_ORDER.indexOf(a),bi=SIGNAL_ORDER.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b,'zh-Hant')})}
function orderStatuses(values){return [...values].sort((a,b)=>{const ap=a.split('｜',1)[0],bp=b.split('｜',1)[0],ai=STATUS_ORDER.indexOf(ap),bi=STATUS_ORDER.indexOf(bp);if((ai<0?99:ai)!==(bi<0?99:bi))return (ai<0?99:ai)-(bi<0?99:bi);const an=Number((a.split('｜')[1]||'').match(/\d+(?:\.\d+)?/)?.[0]||-1),bn=Number((b.split('｜')[1]||'').match(/\d+(?:\.\d+)?/)?.[0]||-1);return bn-an||a.localeCompare(b,'zh-Hant')})}
function setOptions(select,placeholder,values,orderer){const prior=chosen(select).filter(value=>values.includes(value));const selected=new Set(prior);const allSelected=!selected.size;select.innerHTML=`<option value="" ${allSelected?'selected':''}>${placeholder}</option>`+orderer(values).map(value=>`<option value="${esc(value)}" ${selected.has(value)?'selected':''}>${esc(value)}</option>`).join('')}
function normalizeAll(select){const selected=chosen(select);if(selected.length){for(const option of select.options)if(!option.value)option.selected=false}else if(select.options[0])select.options[0].selected=true}
function populateSignalFilter(){setOptions(document.querySelector('#signal'),'全部訊號',[...new Set(data.map(r=>r[8]).filter(Boolean))],orderSignals)}
function populateStatusFilter(){setOptions(document.querySelector('#status'),'全部執行狀態',[...new Set(data.map(r=>r[10]).filter(Boolean))],orderStatuses)}
function syncLinkedFilter(changed){const signal=document.querySelector('#signal'),status=document.querySelector('#status');normalizeAll(changed==='signal'?signal:status);if(changed==='signal'){const picks=chosen(signal);const values=[...new Set(data.filter(r=>!picks.length||picks.includes(r[8])).map(r=>r[10]).filter(Boolean))];setOptions(status,'全部執行狀態',values,orderStatuses)}else{const picks=chosen(status);const values=[...new Set(data.filter(r=>!picks.length||picks.includes(r[10])).map(r=>r[8]).filter(Boolean))];setOptions(signal,'全部訊號',values,orderSignals)}}
function searchText(r){return (r.slice(0,13).join(' ')+' '+JSON.stringify(r[18]||{})).toLowerCase()}
function render(){const q=document.querySelector('#q').value.toLowerCase(),dateRange=document.querySelector('#dateRange');const statuses=chosen(document.querySelector('#status')),signals=chosen(document.querySelector('#signal'));const quickMatch=r=>{if(!quickFilter.type)return true;if(quickFilter.type==='stock'){const code=codeOf(r[1]);return code?code===quickFilter.value:String(r[1]||'').trim()===quickFilter.value}return String(r[18]?.teacher_display_name||r[6]||'').replace(/（猜）|\(猜\)/g,'').trim()===quickFilter.value};const rows=[...data].filter(r=>dateAllowed(r)&&quickMatch(r)&&(!quickFilter.type?(!q||searchText(r).includes(q)):true)&&(!statuses.length||statuses.includes(r[10]))&&(!signals.length||signals.includes(r[8]))).sort((a,b)=>rowTime(b)-rowTime(a));const cols=[0,1,8,10,2,3,11,4,9,'teacher','reason_logic','portfolio','source','evidence'];document.querySelector('#body').innerHTML=rows.map(r=>`<tr>${cols.map(i=>{const meta=r[18]||{};if(i==='teacher')return `<td class="teacher" title="${esc(meta.teacher_id||'')}">${esc(teacherDisplay(r))}</td>`;if(i==='reason_logic')return `<td class="reason"><b>${esc(meta.display_reason||r[7]||'—')}</b><small>${esc(meta.display_logic||'—')}</small></td>`;if(i==='portfolio'){const status=portfolioStatus(r);return `<td class="portfolio"><button type="button" class="portfolio-button ${status.cls}" data-note-key="${esc(rowKey(r))}" title="${esc(r[12]||'點擊新增我的註記')}">${esc(status.label)}</button></td>`}if(i==='source')return `<td class="source">${esc(meta.source_label||'OTHER')}</td>`;if(i==='evidence')return `<td class="evidence">${esc(meta.raw_evidence||'—')}</td>`;const cls=(i===4||i===11?pctClass(r[i])+' ':'')+(i===10?statusClass(r)+' ':'')+(i===2||i===3||i===4||i===9||i===11?'num ':'');const shown=r[i]||'—';const display=i===1?stockLink(shown):i===0?displayDate(r):esc(shown);return `<td class="${cls}">${display}</td>`}).join('')}</tr>`).join('');document.querySelector('#count').textContent=`${rows.length} 筆訊號（${dateRange.options[dateRange.selectedIndex].text}）／共 ${data.length} 筆，其中 ${data.filter(partialDate).length} 筆年份未明`}
function saveEditedNotes(){saveNotes();render()}
async function json(url){let lastError;const sources=[url,'https://api.allorigins.win/raw?url='+encodeURIComponent(url),'https://corsproxy.io/?'+encodeURIComponent(url)];for(const source of sources){try{const response=await fetch(source,{cache:'no-store'});if(response.ok)return await response.json();lastError=new Error(`HTTP ${response.status}`)}catch(error){lastError=error}}throw lastError||new Error('報價來源無回應')}
function numberValue(value){const text=String(value??'').replaceAll(',','').replaceAll('－','-');const match=text.match(/[+-]?\d+(?:\.\d+)?/);return match?Number(match[0]):null}
function fieldOf(record,names){for(const name of names)if(record[name]!==undefined&&record[name]!==null)return record[name];const normalized=Object.keys(record).find(key=>names.some(name=>key.toLowerCase()===name.toLowerCase()));return normalized?record[normalized]:null}
function addQuoteRecords(records,result){for(const record of Array.isArray(records)?records:[]){const code=String(fieldOf(record,['Code','SecuritiesCompanyCode','證券代號','股票代號','代號'])||'').trim();const price=numberValue(fieldOf(record,['ClosingPrice','Close','收盤價','收盤價(元)','成交價','LastPrice']));if(!code||!Number.isFinite(price)||price<=0)continue;const change=numberValue(fieldOf(record,['Change','ChangePrice','漲跌','漲跌價差','UpDown']));const previous=Number.isFinite(change)?price-change:null;result.set(code,{price,previous:Number.isFinite(previous)&&previous>0?previous:null})}}
async function fetchBatchQuotes(codes){const result=new Map();for(let offset=0;offset<codes.length;offset+=100){const batch=codes.slice(offset,offset+100);const response=await fetch('/api/quotes?codes='+encodeURIComponent(batch.join(',')),{cache:'no-store'});if(!response.ok)throw new Error('雲端報價服務沒有回應');const payload=await response.json();addQuoteRecords(payload.listed,result);addQuoteRecords(payload.otc,result)}if(!result.size)throw new Error('雲端報價服務沒有可用資料');return result}
function calculateAvailable(row){if(partialDate(row)){row[4]='年份未明，不計績效';return false}if(row[18]?.exit_scope==='UNKNOWN'){row[4]='賣出範圍未明';return false}if(row[15]==='market'){row[4]='—';return false}if(row[14]==='fixed')return true;const current=Number(row[3]);const entry=entryOf(row[2]);if(!Number.isFinite(current)||current<=0){row[4]='待報價';return false}if(!entry){row[4]='待建議價';return false}row[4]=((current-entry)/entry*100).toFixed(2)+'%';return true}
function quoteClassification(row){const stock=String(row[1]||''),signal=String(row[8]||'');if(/台指期|台積電期|期貨/.test(stock))return '期貨／非股票；不納入現股即時報價';if(signal==='市場訊號')return '非股票／市場訊號；不納入現股即時報價';if(!/^(?:00\d{3}[A-Z]?|\d{4,6})\s+\S+/.test(stock))return '代號需修正；目前無法自動匹配現股報價';return ''}
function setQuoteClassification(row,label){const base=String(row[5]||'').replace(/；?報價分類：[^；]*/g,'').replace(/；+$/,'');row[5]=(base?base+'；':'')+'報價分類：'+label}
function pause(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
async function refreshPrices(){if(priceBusy)return;saveEditedNotes();priceBusy=true;const button=document.querySelector('#quoteButton'),status=document.querySelector('#quoteStatus');button?.classList.add('loading');if(button)button.textContent='正在更新';const rowsByCode=new Map();data.forEach(row=>{const category=quoteClassification(row);if(category){setQuoteClassification(row,category);return}const code=codeOf(row[1]);if(code){if(!rowsByCode.has(code))rowsByCode.set(code,[]);rowsByCode.get(code).push(row)}else setQuoteClassification(row,'代號需修正；目前無法自動匹配現股報價')});const codes=[...rowsByCode.keys()];try{status.textContent=`正在取得 ${codes.length} 支股票的批次報價…`;const quotes=await fetchBatchQuotes(codes);let processed=0,found=0;for(const code of codes){const quote=quotes.get(code);if(quote){found++;for(const row of rowsByCode.get(code)){row[3]=normalizePrice(quote.price);row[11]=quote.previous?((quote.price-quote.previous)/quote.previous*100).toFixed(2)+'%':'—';calculateAvailable(row)}}else for(const row of rowsByCode.get(code))setQuoteClassification(row,'暫無報價；官方來源未匹配此代號');processed++;if(processed===1||(processed-1)%7===0||processed===codes.length){status.textContent=`${processed}/${codes.length} 支股票｜已取得 ${found} 支報價，正在回填與計算績效…`;render();await pause(90)}}saveNotes();status.textContent=`${processed}/${codes.length} 支股票完成｜成功取得 ${found} 支報價｜${new Date().toLocaleTimeString('zh-TW',{hour12:false})}`;render()}catch(error){status.textContent='雲端報價服務暫時沒有回應，請稍後再按「股價更新」。'}finally{priceBusy=false;button?.classList.remove('loading');if(button)button.textContent='股價更新'}}
function signalRef(r,index){const meta=r[18]||{};return meta.event_id||meta.line_message_hash?`${meta.event_id||'LINE:'+meta.line_message_hash}:${codeOf(r[1])}:${r[8]}`:`ROW:${index+1}:${r[0]}:${codeOf(r[1])}:${r[6]}:${r[8]}`}
function excelDate(r){const meta=r[18]||{},value=meta.resolved_date||meta.signal_date;if(!value)return `${r[0]}（年份未明）`;const [y,m,d]=value.split('-').map(Number);return new Date(Date.UTC(y,m-1,d))}
function entryValue(v){const exact=String(v||'').match(/^([\d.]+)進/);return exact?Number(exact[1]):numberValue(v)}
function percentValue(v){const n=numberValue(v);return Number.isFinite(n)?n/100:null}
async function currentReleaseCommit(){if(location.protocol==='file:')return '42f2504cd5062bd769ff6a6175ae69e54a090ca5 (v1.2 source checkpoint)';try{const response=await fetch('/api/release',{cache:'no-store'});if(response.ok){const payload=await response.json();return payload.commit||'unavailable'}}catch(_){}return 'unavailable'}
function styleWorksheet(sheet,widths){sheet.views=[{state:'frozen',ySplit:1,topLeftCell:'A2',activeCell:'A2'}];sheet.autoFilter={from:{row:1,column:1},to:{row:1,column:widths.length}};sheet.columns.forEach((column,index)=>{column.width=widths[index]||16});const header=sheet.getRow(1);header.font={bold:true,color:{argb:'FFFFFFFF'}};header.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF173B57'}};header.alignment={vertical:'middle',horizontal:'center',wrapText:true};header.height=28;sheet.eachRow((row,rowNumber)=>{if(rowNumber>1)row.alignment={vertical:'top',wrapText:true}})}
async function buildXlsxWorkbook(){if(!window.ExcelJS)throw new Error('XLSX 元件尚未載入');const workbook=new ExcelJS.Workbook();workbook.creator='W01 LINE Stock Tracker';workbook.created=new Date();const signals=workbook.addWorksheet('Signals');signals.addRow(['Signal Ref','訊號日','股號','股票','訊號','執行狀態','建議／進場價','現價','現價漲跌幅','績效','出場價位','推薦老師','推薦原因','判斷邏輯','來源','日期精度','價格語意','我的註記','Teacher ID','Signal Definition ID','Definition Version','Direction']);data.forEach((r,index)=>{const meta=r[18]||{},label=String(r[1]||''),code=codeOf(label),name=code?label.replace(new RegExp('^'+code+'\\s*'),''):label;signals.addRow([signalRef(r,index),excelDate(r),code,name,r[8]||'',r[10]||'',entryValue(r[2]),numberValue(r[3]),percentValue(r[11]),percentValue(r[4]),numberValue(r[9]),teacherDisplay(r),meta.display_reason||r[7]||'',r[5]||'',meta.source_label||'OTHER',meta.date_precision||'',meta.exit_price_semantics||meta.entry_price_semantics||'',r[12]||'',meta.teacher_id||'',meta.signal_definition_id||'',meta.signal_definition_version||'',meta.direction||'UNKNOWN'])});signals.getColumn(2).numFmt='yyyy-mm-dd';signals.getColumn(7).numFmt='0.00';signals.getColumn(8).numFmt='0.00';signals.getColumn(9).numFmt='0.00%';signals.getColumn(10).numFmt='0.00%';signals.getColumn(11).numFmt='0.00';styleWorksheet(signals,[31,13,10,18,11,25,14,12,15,12,14,14,34,52,14,16,24,30,18,26,16,12]);const evidence=workbook.addWorksheet('Evidence');evidence.addRow(['Signal Ref','訊號日','股號','股票','老師','訊號','來源','Raw Evidence','Observed At','Source Ref','Event ID','Component ID','Teacher ID','Signal Definition ID']);data.forEach((r,index)=>{const meta=r[18]||{},records=meta.evidence_records||[],label=String(r[1]||''),code=codeOf(label),name=code?label.replace(new RegExp('^'+code+'\\s*'),''):label;(records.length?records:[{source:meta.source_label||'OTHER',raw_text:meta.raw_evidence||''}]).forEach(item=>evidence.addRow([signalRef(r,index),excelDate(r),code,name,teacherDisplay(r),r[8]||'',item.source||'OTHER',item.raw_text||'',item.observed_at||'',item.source_ref||'',item.event_id||meta.event_id||'',item.component_id||'',meta.teacher_id||'',meta.signal_definition_id||'']))});evidence.getColumn(2).numFmt='yyyy-mm-dd';styleWorksheet(evidence,[31,13,10,18,14,11,12,70,24,45,30,34,18,26]);const info=workbook.addWorksheet('Export_Info');const commit=await currentReleaseCommit();const infoRows=[['欄位','值'],['W01 version','W01 v1.4 — Weekly Signal Ingestion & Cross-Source Reconciliation'],['Baseline checkpoint','W01 v1.3 / c8fd408d8419df94fdefdf86b967a28be37c771c'],['Production commit',commit],['Exported at',new Date().toISOString()],['Record count',data.length],['Teacher Registry','W01_TEACHER_REGISTRY_V1 / 1.0'],['Signal Definition Registry','W01_SIGNAL_DEFINITION_REGISTRY_V1 / 1.0'],['Teacher page coverage','61/61; Absolute Viewport Completeness = NOT PROVEN'],['Date caveat',`${data.filter(partialDate).length} 筆年份未明；year_candidate 不等於正式年份`],['SELL caveat','SELL/UNKNOWN 不推定 position=0'],['Schema/export version','xlsx-export-v2-registry'],['Source labels','LINE / WEB / OTHER；同事件可為 LINE + WEB'],['Raw evidence','Evidence 工作表逐來源保留，不由顯示摘要取代']];infoRows.forEach(row=>info.addRow(row));styleWorksheet(info,[30,90]);return workbook}
async function downloadXlsx(){saveEditedNotes();const button=document.querySelector('#xlsxButton'),status=document.querySelector('#xlsxStatus');button?.classList.add('loading');button.disabled=true;status.textContent='正在建立 XLSX…';try{const workbook=await buildXlsxWorkbook(),buffer=await workbook.xlsx.writeBuffer(),url=URL.createObjectURL(new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),link=document.createElement('a'),stamp=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'}).replaceAll('-','').slice(4);link.href=url;link.download=`LINE_股市同學會_投資追蹤表_${stamp}.xlsx`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=`XLSX 已建立：${data.length} 筆訊號`}catch(error){status.textContent='XLSX 匯出失敗：'+(error.message||error)}finally{button?.classList.remove('loading');button.disabled=false}}
function downloadCsv(){saveEditedNotes();const header=['訊號日','股票','訊號','執行狀態','建議價位','現價','現價漲跌幅','績效','推薦老師','推薦原因','判斷邏輯','出場價位','我的註記'];const visible=[0,1,8,10,2,3,11,4,6,7,5,9,12];const csv=[header,...data.map(r=>visible.map(i=>'"'+String(r[i]||'').replaceAll('"','""')+'"'))].map(row=>row.join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download='LINE_股市同學會_投資追蹤表.csv';link.click();URL.revokeObjectURL(link.href)}
void initCloudNotes();document.querySelector('#q').addEventListener('input',()=>{if(quickFilter.type){quickFilter={type:'',value:'',label:''};updateQuickFilterStatus()}render()});document.querySelector('#dateRange').addEventListener('change',render);document.querySelector('#status').addEventListener('change',()=>{syncLinkedFilter('status');render()});document.querySelector('#signal').addEventListener('change',()=>{syncLinkedFilter('signal');render()});document.querySelector('#quickFilterStatus').addEventListener('click',clearQuickFilter);document.querySelector('.market').addEventListener('click',event=>{const target=event.target.closest('[data-filter-type]');if(target)applyQuickFilter(target.dataset.filterType,target.dataset.filterValue,target.dataset.filterLabel)});document.querySelector('#body').addEventListener('click',event=>{const button=event.target.closest('[data-note-key]');if(!button)return;const row=data.find(item=>rowKey(item)===button.dataset.noteKey);if(row)editNote(row)});applyNotes();populateSignalFilter();populateStatusFilter();updateQuickFilterStatus();render();
